        );
    }

    private void addCommercialChanges(
        Map<String, FieldChange> changes,
        CommercialDetails oldValue,
        CommercialDetails newValue
    ) {
        addNestedChange(
            changes,
            "commercial.impactWeight",
            oldValue,
            newValue,
            CommercialDetails::getImpactWeight
        );
        addNestedChange(
            changes,
            "commercial.productionRateCard",
            oldValue,
            newValue,
            CommercialDetails::getProductionRateCard
        );
        addNestedChange(
            changes,
            "commercial.legacyProductionRateCard",
            oldValue,
            newValue,
            CommercialDetails::getLegacyProductionRateCard
        );
        addNestedChange(
            changes,
            "commercial.pricingGrade",
            oldValue,
            newValue,
            CommercialDetails::getPricingGrade
        );
        addNestedChange(
            changes,
            "commercial.priceEntityId",
            oldValue,
            newValue,
            CommercialDetails::getPriceEntityId
        );
        addNestedChange(changes, "commercial.premium", oldValue, newValue, CommercialDetails::getPremium);
    }

    private void addIntegrationChanges(
        Map<String, FieldChange> changes,
        IntegrationDetails oldValue,
        IntegrationDetails newValue
    ) {
        addNestedChange(
            changes,
            "integrations.broadsignDisplayUnitId",
            oldValue,
            newValue,
            IntegrationDetails::getBroadsignDisplayUnitId
        );
        addNestedChange(
            changes,
            "integrations.broadsignFrameId",
            oldValue,
            newValue,
            IntegrationDetails::getBroadsignFrameId
        );
        addNestedChange(
            changes,
            "integrations.broadsignDomainId",
            oldValue,
            newValue,
            IntegrationDetails::getBroadsignDomainId
        );
        addNestedChange(
            changes,
            "integrations.linkedFrameIds",
            oldValue,
            newValue,
            IntegrationDetails::getLinkedFrameIds
        );
    }

    private <T, R> void addNestedChange(
        Map<String, FieldChange> changes,
        String field,
        T oldContainer,
        T newContainer,
        Function<T, R> getter
    ) {
        R oldValue = oldContainer == null ? null : getter.apply(oldContainer);
        R newValue = newContainer == null ? null : getter.apply(newContainer);
        addChange(changes, field, oldValue, newValue);
    }

    private void addChange(
        Map<String, FieldChange> changes,
        String field,
        Object oldValue,
        Object newValue
    ) {
        if (!valuesEqual(oldValue, newValue)) {
            changes.put(field, new FieldChange(asHistoryValue(oldValue), asHistoryValue(newValue)));
        }
    }

    private boolean valuesEqual(Object oldValue, Object newValue) {
        if (oldValue instanceof BigDecimal oldDecimal && newValue instanceof BigDecimal newDecimal) {
            return oldDecimal.compareTo(newDecimal) == 0;
        }
        return Objects.equals(oldValue, newValue);
    }

    private String asHistoryValue(Object value) {
        return value instanceof BigDecimal decimal ? decimal.toPlainString() : Objects.toString(value, null);
    }

    private boolean isDuplicateKey(DataIntegrityViolationException exception) {
        Throwable current = exception;
        while (current != null) {
            if (current instanceof DuplicateKeyException) {
                return true;
            }
            if (current instanceof SQLException sqlException
                && ("23505".equals(sqlException.getSQLState()) || sqlException.getErrorCode() == 1062)) {
                return true;
            }
            current = current.getCause();
        }
        return false;
    }
}
package com.global.ct.frameinventory.specification;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import com.global.ct.frameinventory.dto.FrameSearchCriteria;
import com.global.ct.frameinventory.entity.Frame;

import org.springframework.data.jpa.domain.Specification;

import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.Expression;
import jakarta.persistence.criteria.Path;
import jakarta.persistence.criteria.Predicate;

public final class FrameSpecifications {

    private FrameSpecifications() {
    }

    public static Specification<Frame> matching(FrameSearchCriteria criteria) {
        return (root, query, builder) -> {
            List<Predicate> predicates = new ArrayList<>();

            if (criteria.query() != null) {
                String pattern = "%" + escapeLike(criteria.query().toLowerCase(Locale.ROOT)) + "%";
                predicates.add(builder.or(
                    like(builder, root.get("frameId"), pattern),
                    like(builder, root.get("location").get("address"), pattern),
                    like(builder, root.get("location").get("town"), pattern),
                    like(builder, root.get("site").get("station"), pattern),
                    like(builder, root.get("site").get("airport"), pattern),
                    like(builder, root.get("site").get("siteNumber"), pattern)
                ));
            }

            addExact(predicates, builder, root.get("status"), criteria.status());
            addExact(predicates, builder, root.get("mediaType"), criteria.mediaType());
            addExact(predicates, builder, root.get("environment"), criteria.environment());
            addExact(predicates, builder, root.get("format"), criteria.format());
            addExact(predicates, builder, root.get("location").get("region"), criteria.region());

            return builder.and(predicates.toArray(Predicate[]::new));
        };
    }

    private static Predicate like(CriteriaBuilder builder, Path<?> path, String pattern) {
        return builder.like(lower(builder, path), pattern, '\\');
    }

    private static void addExact(
        List<Predicate> predicates,
        CriteriaBuilder builder,
        Path<?> path,
        String value
    ) {
        if (value != null) {
            predicates.add(builder.equal(lower(builder, path), value.toLowerCase(Locale.ROOT)));
        }
    }

    private static Expression<String> lower(CriteriaBuilder builder, Path<?> path) {
        return builder.lower(path.as(String.class));
    }

    private static String escapeLike(String value) {
        return value.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
    }
}

