      </div>
      <header className="topbar">
        <span>Inventory</span>
        {breadcrumbs.map((breadcrumb, index) => <span className="breadcrumb-part" key={`${breadcrumb}-${index}`}>
          <span className="breadcrumb-separator" aria-hidden="true">/</span>
