import type { FrameFilters as FrameFilterValues } from '../api/frames'

type FilterSuggestions = {
  [K in Exclude<keyof FrameFilterValues, 'status'>]: string[]
}

type Props = {
  query: string
  filters: FrameFilterValues
  suggestions: FilterSuggestions
  onQueryChange: (value: string) => void
  onFilterChange: <K extends keyof FrameFilterValues>(name: K, value: FrameFilterValues[K]) => void
  onClear: () => void
}

export function FrameFilters({ query, filters, suggestions, onQueryChange, onFilterChange, onClear }: Props) {
  const hasFilters = Boolean(
    query.trim() || filters.status || filters.mediaType.trim() ||
    filters.environment.trim() || filters.format.trim() || filters.region.trim(),
  )

  return (
    <aside className="filters" aria-label="Frame filters">
      <div className="filters-header">
        <h2>Filter frames</h2>
      </div>
      <div className="filter-search">
        <div className="field">
          <label htmlFor="frame-search">Search</label>
          <input id="frame-search" className="input search-input" type="search" value={query}
            placeholder="ID, site or location" onChange={(event) => onQueryChange(event.target.value)} />
        </div>
      </div>
      <div className="filter-controls">
        <div className="field">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" className="select" value={filters.status}
            onChange={(event) => onFilterChange('status', event.target.value as FrameFilterValues['status'])}>
            <option value="">All</option><option value="LIVE">LIVE</option><option value="INACTIVE">INACTIVE</option>
          </select>
        </div>
        <StringFilter id="media-type-filter" label="Media type" value={filters.mediaType}
          suggestions={suggestions.mediaType}
          onChange={(value) => onFilterChange('mediaType', value)} />
        <StringFilter id="environment-filter" label="Environment" value={filters.environment}
          suggestions={suggestions.environment}
          onChange={(value) => onFilterChange('environment', value)} />
        <StringFilter id="format-filter" label="Format" value={filters.format}
          suggestions={suggestions.format}
          onChange={(value) => onFilterChange('format', value)} />
        <StringFilter id="region-filter" label="Region" value={filters.region}
          suggestions={suggestions.region}
          onChange={(value) => onFilterChange('region', value)} />
        {hasFilters && <button className="button button-link clear-filters" type="button" onClick={onClear}>Clear all</button>}
      </div>
    </aside>
  )
}

function StringFilter({ id, label, value, suggestions, onChange }: {
  id: string; label: string; value: string; suggestions: string[]; onChange: (value: string) => void
}) {
  const suggestionListId = `${id}-suggestions`

  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input id={id} className="input" type="text" list={suggestionListId} value={value} placeholder="All"
        onChange={(event) => onChange(event.target.value)} />
      <datalist id={suggestionListId}>
        {suggestions.map((suggestion) => <option key={suggestion} value={suggestion} />)}
      </datalist>
    </div>
  )
}
import type { FrameSummary } from '../api/frames'

const dateFormatter = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })

type Props = {
  frames: FrameSummary[]
  onView: (frameId: string) => void
  onEdit: (frameId: string) => void
}

export function FrameTable({ frames, onView, onEdit }: Props) {
  return (
    <div className="table-scroll" role="region" tabIndex={0} aria-label="Scrollable frame inventory table">
      <table className="inventory-table">
        <caption className="sr-only">Frame inventory search results</caption>
        <thead><tr>
          <th scope="col">Frame ID</th><th scope="col">Site</th><th scope="col">Location</th>
          <th scope="col">Media type</th><th scope="col">Format</th><th scope="col">Environment</th>
          <th scope="col">Status</th><th scope="col">Last updated</th><th scope="col"><span className="sr-only">Actions</span></th>
        </tr></thead>
        <tbody>{frames.map((frame) => (
          <tr key={frame.frameId}>
            <td><button className="frame-link frame-id" type="button" onClick={() => onView(frame.frameId)}>
              {frame.frameId}
            </button></td>
            <td><StackedValue primary={frame.station || frame.airport} secondary={frame.address} /></td>
            <td><StackedValue primary={frame.town} secondary={frame.region} /></td>
            <td>{displayValue(frame.mediaType)}</td><td>{displayValue(frame.format)}</td>
            <td>{displayValue(frame.environment)}</td><td><StatusChip status={frame.status} /></td>
            <td><time className="date-value" dateTime={frame.modifiedDate}>{formatDate(frame.modifiedDate)}</time></td>
            <td><button className="button table-edit-button" type="button" onClick={() => onEdit(frame.frameId)}
              aria-label={`Edit frame ${frame.frameId}`}><EditIcon /> Edit</button></td>
          </tr>
        ))}</tbody>
      </table>
    </div>
  )
}

function StackedValue({ primary, secondary }: { primary: string | null; secondary: string | null }) {
  return (
    <span className="stacked-value">
      <span title={primary || undefined}>{displayValue(primary)}</span>
      {secondary && <span className="secondary" title={secondary}>{secondary}</span>}
    </span>
  )
}

function StatusChip({ status }: { status: string }) {
  const normalized = status.toUpperCase()
  const statusClass = normalized === 'LIVE' ? 'status-live' : normalized === 'INACTIVE' ? 'status-inactive' : ''
  return <span className={`status-chip ${statusClass}`.trim()}>{status}</span>
}

function EditIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z" />
  </svg>
}

function formatDate(value: string) {
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? 'â€”' : dateFormatter.format(date)
}

function displayValue(value: string | null) { return value || 'â€”' }
type Props = {
  page: number; size: number; totalElements: number; totalPages: number; disabled: boolean
  onPageChange: (page: number) => void; onSizeChange: (size: number) => void
}

export function Pagination({ page, size, totalElements, totalPages, disabled, onPageChange, onSizeChange }: Props) {
  const start = totalElements === 0 ? 0 : page * size + 1
  const end = Math.min((page + 1) * size, totalElements)
  const displayedPage = totalPages === 0 ? 0 : page + 1

  return (
    <nav className="pagination" aria-label="Inventory pagination">
      <span>Showing {start}â€“{end} of {totalElements}</span><span className="pagination-spacer" />
      <label className="page-size">Rows per page
        <select className="select" value={size} disabled={disabled}
          onChange={(event) => onSizeChange(Number(event.target.value))}>
          <option value={20}>20</option><option value={50}>50</option><option value={100}>100</option>
        </select>
      </label>
      <div className="page-controls">
        <button className="button" type="button" disabled={disabled || page === 0}
          onClick={() => onPageChange(page - 1)}>Previous</button>
        <span className="page-indicator">Page {displayedPage} of {totalPages}</span>
        <button className="button" type="button"
          disabled={disabled || totalPages === 0 || page >= totalPages - 1}
          onClick={() => onPageChange(page + 1)}>Next</button>
      </div>
    </nav>
  )
}

