                            <td>{displayHistoryValue(change.new)}</td>
                          </tr>
                        ))}</tbody>
                      </table>
                    </div>
                  </td>
                </tr>
              )}
            </Fragment>
          )
        })}</tbody>
      </table>
    </div>
  )
}

function SummaryItem({ label, value, children }: { label: string; value?: string | null; children?: React.ReactNode }) {
