import {
  apiErrorsToForm,
  emptyFrameForm,
  frameToForm,
  toCreateRequest,
  toUpdateRequest,
  type FormErrors,
  type FrameFormValues,
} from './frameFormModel'

type Props = {
  mode: 'create' | 'edit'
  frameId?: string
  onCancel: () => void
  onSuccess: (frameId: string, mode: 'create' | 'edit') => void
}

export function FrameEditorPage({ mode, frameId, onCancel, onSuccess }: Props) {
  const headingRef = useRef<HTMLHeadingElement>(null)
  const [initialValues, setInitialValues] = useState<FrameFormValues | null>(mode === 'create' ? emptyFrameForm() : null)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [submitting, setSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [serverErrors, setServerErrors] = useState<FormErrors>({})

  useEffect(() => {
    headingRef.current?.focus()
  }, [])

  useEffect(() => {
    if (mode !== 'edit' || !frameId) return
    const controller = new AbortController()
    getFrame(frameId, controller.signal)
      .then((frame) => setInitialValues(frameToForm(frame)))
      .catch((caught: unknown) => {
        if (caught instanceof DOMException && caught.name === 'AbortError') return
        setLoadError(errorMessage(caught))
      })
    return () => controller.abort()
  }, [frameId, loadAttempt, mode])

  const submit = async (values: FrameFormValues) => {
    if (submitting) return
    setSubmitting(true)
    setSubmitError(null)
    setServerErrors({})
    try {
      const saved = mode === 'create'
        ? await createFrame(toCreateRequest(values))
        : await updateFrame(frameId!, toUpdateRequest(values))
      onSuccess(saved.frameId, mode)
    } catch (caught: unknown) {
      setSubmitError(errorMessage(caught))
      setServerErrors(caught instanceof FrameApiError ? apiErrorsToForm(caught.fieldErrors) : {})
      setSubmitting(false)
    }
  }

  const clearSubmitState = () => {
    if (submitError) setSubmitError(null)
    if (Object.keys(serverErrors).length > 0) setServerErrors({})
  }

  return (
    <>
      <header className="page-header editor-page-header">
        <button className="button back-button" type="button" disabled={submitting} onClick={onCancel} aria-label="Back to frames">
          <BackIcon />
        </button>
        <div>
          <h1 ref={headingRef} tabIndex={-1}>{mode === 'create' ? 'New frame' : 'Edit frame'}</h1>
          <p className="page-meta">
            {mode === 'create' ? 'Add a new physical OOH frame to the inventory.' : `Update inventory details for ${frameId}.`}
          </p>
        </div>
      </header>
      <div className="editor-layout">
        {initialValues ? (
          <FrameForm mode={mode} initialValues={initialValues} submitting={submitting}
            submitError={submitError} serverErrors={serverErrors} onSubmit={submit}
            onCancel={onCancel} onValueChange={clearSubmitState} />
        ) : loadError ? (
          <div className="surface"><div className="state-panel" role="alert"><div className="state-panel-content">
            <span className="state-icon"><AlertIcon /></span>
            <h2>Could not load frame</h2><p>{loadError}</p>
            <button className="button button-primary" type="button" onClick={() => {
              setLoadError(null)
              setInitialValues(null)
              setLoadAttempt((value) => value + 1)
            }}>
              Try again
            </button>
          </div></div></div>
        ) : (
          <div className="surface"><div className="state-panel" role="status"><div className="state-panel-content">
            <span className="state-icon"><span className="loading-spinner" /></span>
            <h2>Loading frame</h2><p>Fetching the latest inventory details.</p>
          </div></div></div>
        )}
      </div>
    </>
  )
}

function errorMessage(caught: unknown) {
  return caught instanceof FrameApiError || caught instanceof Error ? caught.message : 'An unexpected error occurred.'
}

function BackIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="m15 18-6-6 6-6" />
  </svg>
}

function AlertIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="12" cy="12" r="9" /><path d="M12 8v5M12 16h.01" />
  </svg>
}
import { useRef, useState, type FormEvent, type ReactNode } from 'react'
import {
  type FormErrors,
  type FormField,
  type FrameFormValues,
  validateFrameForm,
} from './frameFormModel'
import { COUNTRY_OPTIONS } from './countries'

type Props = {
  mode: 'create' | 'edit'
  initialValues: FrameFormValues
  submitting: boolean
  submitError: string | null
  serverErrors: FormErrors
  onSubmit: (values: FrameFormValues) => void
  onCancel: () => void
  onValueChange: () => void
}

export function FrameForm({
  mode, initialValues, submitting, submitError, serverErrors, onSubmit, onCancel, onValueChange,
}: Props) {
  const [values, setValues] = useState(initialValues)
  const [clientErrors, setClientErrors] = useState<FormErrors>({})
  const errorSummaryRef = useRef<HTMLDivElement>(null)
  const errors = { ...serverErrors, ...clientErrors }

  const changeValue = (field: FormField, value: string) => {
    setValues((current) => ({ ...current, [field]: value }))
    setClientErrors((current) => removeError(current, field))
    onValueChange()
  }

  const validateField = (field: FormField) => {
    const nextError = validateFrameForm(values, mode)[field]
    setClientErrors((current) => nextError
      ? { ...current, [field]: nextError }
      : removeError(current, field))
  }

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (submitting) return
    const nextErrors = validateFrameForm(values, mode)
    setClientErrors(nextErrors)
    if (Object.keys(nextErrors).length > 0) {
      window.requestAnimationFrame(() => errorSummaryRef.current?.focus())
      return
    }
    onSubmit(values)
  }

  const fieldProps = (field: FormField) => ({
    field,
    value: values[field],
    error: errors[field],
    onChange: changeValue,
    onBlur: validateField,
  })

  return (
    <form className="frame-form" noValidate onSubmit={submit} aria-busy={submitting}>
      {(submitError || Object.keys(clientErrors).length > 0) && (
        <div className="form-error-summary" role="alert" tabIndex={-1} ref={errorSummaryRef}>
          <strong>{Object.keys(clientErrors).length > 0 ? 'Check the highlighted fields.' : 'Could not save frame.'}</strong>
          {submitError && <span>{submitError}</span>}
        </div>
      )}

      <div className="surface form-surface">
        <FormSection title="Basics and lifecycle" description="Core inventory classification and current operating status."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('frameId')} label="Frame ID" required={mode === 'create'} readOnly={mode === 'edit'} maxLength={64}
              help={mode === 'edit' ? 'Frame ID cannot be changed.' : undefined} />
            <TextField {...fieldProps('mediaType')} label="Media type" required placeholder="e.g. DIGITAL" />
            <TextField {...fieldProps('format')} label="Format" required placeholder="e.g. D6" />
            <TextField {...fieldProps('environment')} label="Environment" placeholder="e.g. UNDERGROUND" />
            <SelectField {...fieldProps('status')} label="Status" required>
              <option value="LIVE">LIVE</option>
              <option value="INACTIVE">INACTIVE</option>
            </SelectField>
            <TextField {...fieldProps('statusReason')} label="Status reason" wide multiline />
          </div>
        </FormSection>

        <FormSection title="Location" description="Postal address, geographic identifiers and coordinates."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('postcode')} label="Postcode" required />
            <TextField {...fieldProps('region')} label="Region" required />
            <TextField {...fieldProps('town')} label="Town" required />
            <TextField {...fieldProps('address')} label="Address" wide multiline />
            <SelectField {...fieldProps('countryCode')} label="Country">
              <option value="">Not set</option>
              {COUNTRY_OPTIONS.map((country) => (
                <option key={country.code} value={country.code}>{country.code} - {country.name}</option>
              ))}
            </SelectField>
            <TextField {...fieldProps('postcodeArea')} label="Postcode area" />
            <TextField {...fieldProps('postcodeDistrict')} label="Postcode district" />
            <TextField {...fieldProps('postcodeSector')} label="Postcode sector" />
            <TextField {...fieldProps('postcodeUnit')} label="Postcode unit" />
            <TextField {...fieldProps('longitude')} label="Longitude" inputMode="decimal" />
            <TextField {...fieldProps('latitude')} label="Latitude" inputMode="decimal" />
            <TextField {...fieldProps('distanceToClosestSchool')} label="Distance to closest school" inputMode="numeric"
              help="Metres" />
            <TextField {...fieldProps('rawLocationPoint')} label="Raw location point" />
            <TextField {...fieldProps('locationId')} label="Location ID" />
          </div>
        </FormSection>

        <FormSection title="Site" description="Identifiers and placement within the physical site."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('siteNumber')} label="Site number" required />
            <TextField {...fieldProps('inventorySiteNumber')} label="Inventory site number" />
            <TextField {...fieldProps('panelNumber')} label="Panel number" />
            <TextField {...fieldProps('station')} label="Station" />
            <TextField {...fieldProps('airport')} label="Airport" />
          </div>
        </FormSection>

        <FormSection title="Technical" description="Display size, illumination and delivery details."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('illuminationTypeId')} label="Illumination type ID" />
            <TextField {...fieldProps('numberOfSlots')} label="Number of slots" inputMode="numeric" />
            <TextField {...fieldProps('sizeCode')} label="Size code" />
            <TextField {...fieldProps('sizeGroupCode')} label="Size group code" />
            <TextField {...fieldProps('aspectRatioCode')} label="Aspect ratio code" />
            <TextField {...fieldProps('sizeCategory')} label="Size category" />
            <TextField {...fieldProps('pixelWidth')} label="Pixel width" inputMode="numeric" />
            <TextField {...fieldProps('pixelHeight')} label="Pixel height" inputMode="numeric" />
          </div>
        </FormSection>

        <FormSection title="Commercial" description="Pricing references and commercial weighting."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('impactWeight')} label="Impact weight" inputMode="decimal" />
            <TextField {...fieldProps('pricingGrade')} label="Pricing grade" />
            <TextField {...fieldProps('priceEntityId')} label="Price entity ID" />
            <TextField {...fieldProps('productionRateCard')} label="Production rate card" />
            <TextField {...fieldProps('legacyProductionRateCard')} label="Legacy production rate card" />
            <SelectField {...fieldProps('premium')} label="Premium">
              <option value="">Not set</option>
              <option value="true">Yes</option>
              <option value="false">No</option>
            </SelectField>
          </div>
        </FormSection>

        <FormSection title="Integrations" description="Identifiers used by Broadsign and linked inventory records."
          disabled={submitting} last>
          <div className="form-grid form-grid-two">
            <TextField {...fieldProps('broadsignDisplayUnitId')} label="Broadsign display unit ID" />
            <TextField {...fieldProps('broadsignFrameId')} label="Broadsign frame ID" />
            <TextField {...fieldProps('broadsignDomainId')} label="Broadsign domain ID" />
            <TextField {...fieldProps('linkedFrameIds')} label="Linked frame IDs" multiline />
          </div>
        </FormSection>
      </div>

      <div className="form-actions">
        <span>{mode === 'create' ? 'Create a new inventory frame' : `Editing ${values.frameId}`}</span>
        <div className="form-actions-buttons">
          <button className="button" type="button" disabled={submitting} onClick={onCancel}>Cancel</button>
          <button className="button button-primary" type="submit" disabled={submitting}>
            {submitting && <span className="loading-spinner loading-spinner-small" aria-hidden="true" />}
            {submitting ? 'Savingâ€¦' : mode === 'create' ? 'Create frame' : 'Save changes'}
          </button>
        </div>
      </div>
    </form>
  )
}

function FormSection({ title, description, disabled, last = false, children }: {
  title: string; description: string; disabled: boolean; last?: boolean; children: ReactNode
}) {
  return (
    <fieldset className={`form-section${last ? ' form-section-last' : ''}`} disabled={disabled}>
      <legend>{title}</legend>
      <p>{description}</p>
      {children}
    </fieldset>
  )
}

type FieldProps = {
  field: FormField
  label: string
  value: string
  error?: string
  required?: boolean
  wide?: boolean
  help?: string
  onChange: (field: FormField, value: string) => void
  onBlur: (field: FormField) => void
}

function TextField({
  field, label, value, error, required, wide, help, onChange, onBlur, multiline = false,
  readOnly = false, maxLength, placeholder, inputMode,
}: FieldProps & {
  multiline?: boolean; readOnly?: boolean; maxLength?: number; placeholder?: string
  inputMode?: 'decimal' | 'numeric'
}) {
  const errorId = `${field}-error`
  const helpId = `${field}-help`
  const describedBy = [error ? errorId : '', help ? helpId : ''].filter(Boolean).join(' ') || undefined
  const controlProps = {
    id: field,
    name: field,
    className: `input${error ? ' input-error' : ''}`,
    value,
    placeholder,
    readOnly,
    maxLength,
    inputMode,
    'aria-invalid': Boolean(error),
    'aria-required': required || undefined,
    'aria-describedby': describedBy,
    onChange: (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => onChange(field, event.target.value),
    onBlur: () => onBlur(field),
  }

  return (
    <div className={`field form-field${wide ? ' form-field-wide' : ''}`}>
      <label htmlFor={field}>{label}{required && <RequiredMark />}</label>
      {multiline ? <textarea {...controlProps} /> : <input type="text" {...controlProps} />}
      {help && <span className="field-help" id={helpId}>{help}</span>}
      {error && <span className="field-error" id={errorId}>{error}</span>}
    </div>
  )
}

function SelectField({ field, label, value, error, required, wide, onChange, onBlur, children }: FieldProps & {
  children: ReactNode
}) {
  const errorId = `${field}-error`
  return (
    <div className={`field form-field${wide ? ' form-field-wide' : ''}`}>
      <label htmlFor={field}>{label}{required && <RequiredMark />}</label>
      <select id={field} name={field} className={`select${error ? ' input-error' : ''}`} value={value}
        aria-invalid={Boolean(error)} aria-required={required || undefined}
        aria-describedby={error ? errorId : undefined}
        onChange={(event) => onChange(field, event.target.value)} onBlur={() => onBlur(field)}>
        {children}
      </select>
      {error && <span className="field-error" id={errorId}>{error}</span>}
    </div>
  )
}

function RequiredMark() {
  return <span className="required-mark" aria-hidden="true"> *</span>
}

function removeError(errors: FormErrors, field: FormField): FormErrors {
  if (!errors[field]) return errors
  const next = { ...errors }
  delete next[field]
  return next
}
import type {
  CommercialDetails,
  CreateFrameRequest,
  Frame,
  FrameFieldError,
  IntegrationDetails,
  TechnicalDetails,
  UpdateFrameRequest,
} from '../api/frames'

export type FrameFormValues = {
  frameId: string
  mediaType: string
  format: string
  environment: string
  status: string
  statusReason: string
  postcode: string
  postcodeArea: string
  postcodeDistrict: string
  postcodeSector: string
  postcodeUnit: string
  address: string
  region: string
  countryCode: string
  town: string
  longitude: string
  latitude: string
  distanceToClosestSchool: string
  rawLocationPoint: string
  locationId: string
  siteNumber: string
  inventorySiteNumber: string
  panelNumber: string
  station: string
  airport: string
  illuminationTypeId: string
  numberOfSlots: string
  sizeCode: string
  sizeGroupCode: string
  aspectRatioCode: string
  sizeCategory: string
  pixelHeight: string
  pixelWidth: string
  impactWeight: string
  productionRateCard: string
  legacyProductionRateCard: string
  pricingGrade: string
  priceEntityId: string
  premium: '' | 'true' | 'false'
  broadsignDisplayUnitId: string
  broadsignFrameId: string
  broadsignDomainId: string
  linkedFrameIds: string
}

export type FormField = keyof FrameFormValues
export type FormErrors = Partial<Record<FormField, string>>

export function emptyFrameForm(): FrameFormValues {
  return {
    frameId: '', mediaType: '', format: '', environment: '', status: 'LIVE', statusReason: '',
    postcode: '', postcodeArea: '', postcodeDistrict: '', postcodeSector: '', postcodeUnit: '',
    address: '', region: '', countryCode: '', town: '', longitude: '', latitude: '',
    distanceToClosestSchool: '', rawLocationPoint: '', locationId: '',
    siteNumber: '', inventorySiteNumber: '', panelNumber: '', station: '', airport: '',
    illuminationTypeId: '', numberOfSlots: '', sizeCode: '', sizeGroupCode: '', aspectRatioCode: '',
    sizeCategory: '', pixelHeight: '', pixelWidth: '', impactWeight: '', productionRateCard: '',
    legacyProductionRateCard: '', pricingGrade: '', priceEntityId: '', premium: '',
    broadsignDisplayUnitId: '', broadsignFrameId: '', broadsignDomainId: '', linkedFrameIds: '',
  }
}

export function frameToForm(frame: Frame): FrameFormValues {
  return {
    frameId: frame.frameId,
    mediaType: frame.mediaType ?? '',
    format: frame.format ?? '',
    environment: frame.environment ?? '',
    status: frame.status ?? '',
    statusReason: frame.statusReason ?? '',
    postcode: frame.location?.postcode ?? '',
    postcodeArea: frame.location?.postcodeArea ?? '',
    postcodeDistrict: frame.location?.postcodeDistrict ?? '',
    postcodeSector: frame.location?.postcodeSector ?? '',
    postcodeUnit: frame.location?.postcodeUnit ?? '',
    address: frame.location?.address ?? '',
    region: frame.location?.region ?? '',
    countryCode: frame.location?.countryCode ?? '',
    town: frame.location?.town ?? '',
    longitude: valueToString(frame.location?.longitude),
    latitude: valueToString(frame.location?.latitude),
    distanceToClosestSchool: valueToString(frame.location?.distanceToClosestSchool),
    rawLocationPoint: frame.location?.rawLocationPoint ?? '',
    locationId: frame.location?.locationId ?? '',
    siteNumber: frame.site?.siteNumber ?? '',
    inventorySiteNumber: frame.site?.inventorySiteNumber ?? '',
    panelNumber: frame.site?.panelNumber ?? '',
    station: frame.site?.station ?? '',
    airport: frame.site?.airport ?? '',
    illuminationTypeId: frame.technical?.illuminationTypeId ?? '',
    numberOfSlots: valueToString(frame.technical?.numberOfSlots),
    sizeCode: frame.technical?.sizeCode ?? '',
    sizeGroupCode: frame.technical?.sizeGroupCode ?? '',
    aspectRatioCode: frame.technical?.aspectRatioCode ?? '',
    sizeCategory: frame.technical?.sizeCategory ?? '',
    pixelHeight: valueToString(frame.technical?.pixelHeight),
    pixelWidth: valueToString(frame.technical?.pixelWidth),
    impactWeight: valueToString(frame.commercial?.impactWeight),
    productionRateCard: frame.commercial?.productionRateCard ?? '',
    legacyProductionRateCard: frame.commercial?.legacyProductionRateCard ?? '',
    pricingGrade: frame.commercial?.pricingGrade ?? '',
    priceEntityId: frame.commercial?.priceEntityId ?? '',
    premium: frame.commercial?.premium == null ? '' : String(frame.commercial.premium) as 'true' | 'false',
    broadsignDisplayUnitId: frame.integrations?.broadsignDisplayUnitId ?? '',
    broadsignFrameId: frame.integrations?.broadsignFrameId ?? '',
    broadsignDomainId: frame.integrations?.broadsignDomainId ?? '',
    linkedFrameIds: frame.integrations?.linkedFrameIds ?? '',
  }
}

export function validateFrameForm(values: FrameFormValues, mode: 'create' | 'edit'): FormErrors {
  const errors: FormErrors = {}
  if (mode === 'create') {
    required(errors, 'frameId', values.frameId, 'Frame ID is required.')
    if (values.frameId.trim().length > 64) errors.frameId = 'Frame ID must be 64 characters or fewer.'
  }
  required(errors, 'mediaType', values.mediaType, 'Media type is required.')
  required(errors, 'format', values.format, 'Format is required.')
  if (values.status !== 'LIVE' && values.status !== 'INACTIVE') errors.status = 'Select a status.'
  required(errors, 'postcode', values.postcode, 'Postcode is required.')
  required(errors, 'region', values.region, 'Region is required.')
  required(errors, 'town', values.town, 'Town is required.')
  required(errors, 'siteNumber', values.siteNumber, 'Site number is required.')

  decimal(errors, 'longitude', values.longitude, 'Longitude must be a number.')
  decimal(errors, 'latitude', values.latitude, 'Latitude must be a number.')
  decimal(errors, 'impactWeight', values.impactWeight, 'Impact weight must be a number.')
  integer(errors, 'distanceToClosestSchool', values.distanceToClosestSchool, 'School distance must be a whole number.')
  integer(errors, 'numberOfSlots', values.numberOfSlots, 'Number of slots must be a whole number.')
  integer(errors, 'pixelHeight', values.pixelHeight, 'Pixel height must be a whole number.')
  integer(errors, 'pixelWidth', values.pixelWidth, 'Pixel width must be a whole number.')
  return errors
}

export function apiErrorsToForm(errors: FrameFieldError[]): FormErrors {
  const fields: Record<string, FormField> = {
    frameId: 'frameId', mediaType: 'mediaType', format: 'format', status: 'status',
    'location.postcode': 'postcode', 'location.region': 'region', 'location.town': 'town',
    'site.siteNumber': 'siteNumber',
  }
  return errors.reduce<FormErrors>((result, error) => {
    const field = fields[error.field]
    if (field) result[field] = error.message
    return result
  }, {})
}

export function toCreateRequest(values: FrameFormValues): CreateFrameRequest {
  return { frameId: values.frameId.trim(), ...toWritableRequest(values) }
}

export function toUpdateRequest(values: FrameFormValues): UpdateFrameRequest {
  return toWritableRequest(values)
}

function toWritableRequest(values: FrameFormValues): UpdateFrameRequest {
  const technical: TechnicalDetails = {
    illuminationTypeId: optional(values.illuminationTypeId),
    numberOfSlots: optionalInteger(values.numberOfSlots),
    sizeCode: optional(values.sizeCode),
    sizeGroupCode: optional(values.sizeGroupCode),
    aspectRatioCode: optional(values.aspectRatioCode),
    sizeCategory: optional(values.sizeCategory),
    pixelHeight: optionalInteger(values.pixelHeight),
    pixelWidth: optionalInteger(values.pixelWidth),
  }
  const commercial: CommercialDetails = {
    impactWeight: optionalNumber(values.impactWeight),
    productionRateCard: optional(values.productionRateCard),
    legacyProductionRateCard: optional(values.legacyProductionRateCard),
    pricingGrade: optional(values.pricingGrade),
    priceEntityId: optional(values.priceEntityId),
    premium: values.premium === '' ? null : values.premium === 'true',
  }
  const integrations: IntegrationDetails = {
    broadsignDisplayUnitId: optional(values.broadsignDisplayUnitId),
    broadsignFrameId: optional(values.broadsignFrameId),
    broadsignDomainId: optional(values.broadsignDomainId),
    linkedFrameIds: optional(values.linkedFrameIds),
  }

  return {
    mediaType: values.mediaType.trim(),
    format: values.format.trim(),
    environment: optional(values.environment),
    status: values.status as 'LIVE' | 'INACTIVE',
    statusReason: optional(values.statusReason),
    location: {
      postcode: values.postcode.trim(),
      postcodeArea: optional(values.postcodeArea),
      postcodeDistrict: optional(values.postcodeDistrict),
      postcodeSector: optional(values.postcodeSector),
      postcodeUnit: optional(values.postcodeUnit),
      address: optional(values.address),
      region: values.region.trim(),
      countryCode: optional(values.countryCode),
      town: values.town.trim(),
      longitude: optionalNumber(values.longitude),
      latitude: optionalNumber(values.latitude),
      distanceToClosestSchool: optionalInteger(values.distanceToClosestSchool),
      rawLocationPoint: optional(values.rawLocationPoint),
      locationId: optional(values.locationId),
    },
    site: {
      siteNumber: values.siteNumber.trim(),
      inventorySiteNumber: optional(values.inventorySiteNumber),
      panelNumber: optional(values.panelNumber),
      station: optional(values.station),
      airport: optional(values.airport),
    },
    technical: hasValue(technical) ? technical : null,
    commercial: hasValue(commercial) ? commercial : null,
    integrations: hasValue(integrations) ? integrations : null,
  }
}

function required(errors: FormErrors, field: FormField, value: string, message: string) {
  if (!value.trim()) errors[field] = message
}

function decimal(errors: FormErrors, field: FormField, value: string, message: string) {
  const normalized = value.trim()
  if (normalized && (
    !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(normalized) ||
    !Number.isFinite(Number(normalized))
  )) errors[field] = message
}

function integer(errors: FormErrors, field: FormField, value: string, message: string) {
  const normalized = value.trim()
  if (!normalized) return
  if (!/^[+-]?\d+$/.test(normalized)) {
    errors[field] = message
    return
  }
  const number = Number(normalized)
  if (number < -2147483648 || number > 2147483647) errors[field] = 'Value is outside the supported whole-number range.'
}

function optional(value: string): string | null {
  return value.trim() || null
}

function optionalNumber(value: string): number | null {
  return value.trim() ? Number(value.trim()) : null
}

