export type FrameSummary = {
  frameId: string
  mediaType: string
  format: string
  environment: string | null
  status: string
  modifiedDate: string
  address: string | null
  town: string | null
  region: string | null
  station: string | null
  airport: string | null
}

export type LocationDetails = {
  postcode: string
  postcodeArea: string | null
  postcodeDistrict: string | null
  postcodeSector: string | null
  postcodeUnit: string | null
  address: string | null
  region: string
  countryCode: string | null
  town: string
  longitude: number | null
  latitude: number | null
  distanceToClosestSchool: number | null
  rawLocationPoint: string | null
  locationId: string | null
}

export type SiteDetails = {
  siteNumber: string
  inventorySiteNumber: string | null
  panelNumber: string | null
  station: string | null
  airport: string | null
}

export type TechnicalDetails = {
  illuminationTypeId: string | null
  numberOfSlots: number | null
  sizeCode: string | null
  sizeGroupCode: string | null
  aspectRatioCode: string | null
  sizeCategory: string | null
  pixelHeight: number | null
  pixelWidth: number | null
}

export type CommercialDetails = {
  impactWeight: number | null
  productionRateCard: string | null
  legacyProductionRateCard: string | null
  pricingGrade: string | null
  priceEntityId: string | null
  premium: boolean | null
}

export type IntegrationDetails = {
  broadsignDisplayUnitId: string | null
  broadsignFrameId: string | null
  broadsignDomainId: string | null
  linkedFrameIds: string | null
}

export type FrameWritableDetails = {
  mediaType: string
  format: string
  environment: string | null
  status: 'LIVE' | 'INACTIVE'
  statusReason: string | null
  location: LocationDetails
  site: SiteDetails
  technical: TechnicalDetails | null
  commercial: CommercialDetails | null
  integrations: IntegrationDetails | null
}

export type CreateFrameRequest = FrameWritableDetails & { frameId: string }
export type UpdateFrameRequest = FrameWritableDetails

export type Frame = FrameWritableDetails & {
  frameId: string
  createdDate: string
  modifiedDate: string
}

export type FrameHistoryEventType = 'CREATED' | 'IMPORTED' | 'UPDATED'
export type FrameHistorySource = 'MANUAL' | 'CSV_UPLOAD'

export type FrameFieldChange = {
  old: string | null
  new: string | null
}

export type FrameHistoryEntry = {
  eventType: FrameHistoryEventType
  occurredAt: string
  source: FrameHistorySource
  changedFields: Record<string, FrameFieldChange>
}

export type FramePage = {
  items: FrameSummary[]
  page: number
  size: number
  totalElements: number
  totalPages: number
}

export type FrameCsvImportError = {
  rowNumber: number
  frameId: string | null
  reason: string
}

export type FrameCsvImportSummary = {
  totalRows: number
  created: number
  duplicates: number
  failed: number
  errors: FrameCsvImportError[]
}

export type FrameFilters = {
  status: '' | 'LIVE' | 'INACTIVE'
  mediaType: string
  environment: string
  format: string
  region: string
}

export type GetFramesParams = FrameFilters & { page: number; size: number; q: string }
export type FrameFieldError = { field: string; message: string }
type ProblemDetail = { title?: string; detail?: string; errors?: FrameFieldError[] }

export class FrameApiError extends Error {
  status: number
  fieldErrors: FrameFieldError[]

  constructor(message: string, status: number, fieldErrors: FrameFieldError[] = []) {
    super(message)
    this.name = 'FrameApiError'
    this.status = status
    this.fieldErrors = fieldErrors
  }
}

export async function getFrames(
  params: GetFramesParams,
  signal?: AbortSignal,
): Promise<FramePage> {
  const searchParams = new URLSearchParams({ page: String(params.page), size: String(params.size) })
  addIfPresent(searchParams, 'q', params.q)
  addIfPresent(searchParams, 'status', params.status)
  addIfPresent(searchParams, 'mediaType', params.mediaType)
  addIfPresent(searchParams, 'environment', params.environment)
  addIfPresent(searchParams, 'format', params.format)
  addIfPresent(searchParams, 'region', params.region)

  return request<FramePage>(`/api/frames?${searchParams.toString()}`, { signal })
}

export function getFrame(frameId: string, signal?: AbortSignal): Promise<Frame> {
  return request<Frame>(`/api/frames/${encodeURIComponent(frameId)}`, { signal })
}

export function getFrameHistory(frameId: string, signal?: AbortSignal): Promise<FrameHistoryEntry[]> {
  return request<FrameHistoryEntry[]>(`/api/frames/${encodeURIComponent(frameId)}/history`, { signal })
}

export function createFrame(payload: CreateFrameRequest): Promise<Frame> {
  return request<Frame>('/api/frames', jsonRequest('POST', payload))
}

export function updateFrame(frameId: string, payload: UpdateFrameRequest): Promise<Frame> {
  return request<Frame>(`/api/frames/${encodeURIComponent(frameId)}`, jsonRequest('PUT', payload))
}

export function importFrames(file: File): Promise<FrameCsvImportSummary> {
  const body = new FormData()
  body.append('file', file)
  return request<FrameCsvImportSummary>('/api/frames/import', {
    method: 'POST',
    headers: { Accept: 'application/json' },
    body,
  })
}

function addIfPresent(params: URLSearchParams, key: string, value: string) {
  const normalizedValue = value.trim()
  if (normalizedValue) params.set(key, normalizedValue)
}

function jsonRequest(method: 'POST' | 'PUT', body: CreateFrameRequest | UpdateFrameRequest): RequestInit {
  return {
    method,
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }
}

async function request<T>(url: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: init.headers ?? { Accept: 'application/json' },
  })
  if (!response.ok) throw await readApiError(response)
  return (await response.json()) as T
}

async function readApiError(response: Response): Promise<FrameApiError> {
  try {
    const problem = (await response.json()) as ProblemDetail
    return new FrameApiError(
      problem.detail || problem.title || `Request failed with status ${response.status}`,
      response.status,
      Array.isArray(problem.errors) ? problem.errors : [],
    )
  } catch {
    return new FrameApiError(`Request failed with status ${response.status}`, response.status)
  }
}
import type { FrameFilters as FrameFilterValues } from '../api/frames'

type FilterSuggestions = {
  [K in Exclude<keyof FrameFilterValues, 'status'>]: string[]
}

type Props = {
  query: string
  filters: FrameFilterValues
  suggestions: FilterSuggestions
  onQueryChange: (value: string) => void
  onFilterChange: <K extends keyof FrameFilterValues>(name: K, value: FrameFilterValues[K]) => void
  onClear: () => void
}

export function FrameFilters({ query, filters, suggestions, onQueryChange, onFilterChange, onClear }: Props) {
  const hasFilters = Boolean(
    query.trim() || filters.status || filters.mediaType.trim() ||
    filters.environment.trim() || filters.format.trim() || filters.region.trim(),
  )

  return (
    <aside className="filters" aria-label="Frame filters">
      <div className="filters-header">
        <h2>Filter frames</h2>
      </div>
      <div className="filter-search">
        <div className="field">
          <label htmlFor="frame-search">Search</label>
          <input id="frame-search" className="input search-input" type="search" value={query}
            placeholder="ID, site or location" onChange={(event) => onQueryChange(event.target.value)} />
        </div>
      </div>
      <div className="filter-controls">
        <div className="field">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" className="select" value={filters.status}
            onChange={(event) => onFilterChange('status', event.target.value as FrameFilterValues['status'])}>
            <option value="">All</option><option value="LIVE">LIVE</option><option value="INACTIVE">INACTIVE</option>
          </select>
        </div>
        <StringFilter id="media-type-filter" label="Media type" value={filters.mediaType}
          suggestions={suggestions.mediaType}
          onChange={(value) => onFilterChange('mediaType', value)} />
        <StringFilter id="environment-filter" label="Environment" value={filters.environment}
          suggestions={suggestions.environment}
          onChange={(value) => onFilterChange('environment', value)} />
        <StringFilter id="format-filter" label="Format" value={filters.format}
          suggestions={suggestions.format}
          onChange={(value) => onFilterChange('format', value)} />
        <StringFilter id="region-filter" label="Region" value={filters.region}
          suggestions={suggestions.region}
          onChange={(value) => onFilterChange('region', value)} />
        {hasFilters && <button className="button button-link clear-filters" type="button" onClick={onClear}>Clear all</button>}
      </div>
    </aside>
  )
}

function StringFilter({ id, label, value, suggestions, onChange }: {
  id: string; label: string; value: string; suggestions: string[]; onChange: (value: string) => void
}) {
  const suggestionListId = `${id}-suggestions`

  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input id={id} className="input" type="text" list={suggestionListId} value={value} placeholder="All"
        onChange={(event) => onChange(event.target.value)} />
      <datalist id={suggestionListId}>
        {suggestions.map((suggestion) => <option key={suggestion} value={suggestion} />)}
      </datalist>
    </div>
  )
}

