const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds))

const pages = await (await fetch('http://localhost:9222/json')).json()
const page = pages.find((candidate) =>
  candidate.type === 'page' && candidate.url.startsWith('http://localhost:3000'),
)
const socket = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  socket.onopen = resolve
  socket.onerror = reject
})

let commandId = 0
const pending = new Map()
const urls = []
const consoleMessages = []
socket.onmessage = (event) => {
  const message = JSON.parse(event.data)
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message)
    pending.delete(message.id)
  }
  if (message.method === 'Network.requestWillBeSent' && message.params.request.url.includes('/api/frames?')) {
    urls.push(message.params.request.url)
  }
  if (message.method === 'Runtime.consoleAPICalled') {
    consoleMessages.push(message.params.args.map((argument) => argument.value ?? argument.description))
  }
}
const send = (method, params = {}) => new Promise((resolve) => {
  const id = ++commandId
  pending.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})

await send('Network.enable')
await send('Runtime.enable')
await send('Page.reload', { ignoreCache: true })
await sleep(1_000)
urls.length = 0
consoleMessages.length = 0
const before = await send('Runtime.evaluate', {
  expression: `({
    value: document.querySelector('#environment-filter')?.value,
    clearVisible: Boolean(document.querySelector('.clear-filters')),
  })`,
  returnByValue: true,
})
await send('Runtime.evaluate', {
  expression: `(() => {
    window.__filterTraceUrls = []
    if (!window.__filterTraceOriginalFetch) window.__filterTraceOriginalFetch = window.fetch
    window.fetch = (...args) => {
      window.__filterTraceUrls.push(String(args[0]))
      return window.__filterTraceOriginalFetch(...args)
    }
    const input = document.querySelector('#environment-filter')
    input.focus()
    return document.activeElement === input
  })()`,
  returnByValue: true,
})
for (const character of 'sowmya') {
  await send('Input.dispatchKeyEvent', {
    type: 'keyDown',
    key: character,
    code: `Key${character.toUpperCase()}`,
    text: character,
    unmodifiedText: character,
  })
  await send('Input.dispatchKeyEvent', {
    type: 'keyUp',
    key: character,
    code: `Key${character.toUpperCase()}`,
  })
}
await sleep(2_000)
const state = await send('Runtime.evaluate', {
  expression: `({
    value: document.querySelector('#environment-filter')?.value,
    meta: document.querySelector('.page-meta')?.textContent,
    empty: document.querySelector('.state-panel h2')?.textContent,
    clearVisible: Boolean(document.querySelector('.clear-filters')),
    fetchUrls: window.__filterTraceUrls,
  })`,
  returnByValue: true,
})

console.log(JSON.stringify({ before: before.result.result.value, urls, consoleMessages, state: state.result.result.value }, null, 2))
socket.close()

